"""Static pages, feeds and indexes for KENGO'S SYNESTHESIA, generated by build.py from
world/news.json, world/plates.json and world/weekly.json.

  YYYY/MM/DD/            one page per day (permalink): Kengo's Note, the day's Digital Art, the day's Daily Masterwork,
                         the stories, From Japan and Objects — with OGP, JSON-LD and hreflang
  en/, en/YYYY/MM/DD/    the same in English only
  notes/                 every Kengo's Note
  weekly/, weekly/<id>/  Weekly Synesthesia (the Sunday column)
  japan/                 From Japan: every story about something made in Japan
  objects/               Objects: one good thing a day
  rights/ + rights.json  the rights ledger of every Daily Masterwork
  feed.xml / feed.json   Atom and JSON Feed, one entry per day
  pins.xml               RSS with images (Daily Masterworks and Digital Art) for Pinterest auto-publish
  search.json            the index behind the page's search box
"""
import json, re, os
from datetime import date, datetime, timedelta
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
WORLD = ROOT / 'world'
BASE = 'https://www.kengo-umetani.com/synesthesia-world/'
CATS = [('fashion', 'Fashion'), ('music', 'Music'), ('design', 'Design')]
NAV = [('Note', '#note'), ('Digital Art', '#art'), ('Daily Masterworks', '#plates-sec'), ('Today', '#today'), ('Archive', '#archive'),
       ('Weekly', 'weekly/'), ('From Japan', 'japan/'), ('Objects', 'objects/'), ('Synesthesia Music', '#sound'), ('Index', '#index'), ('Credits', '#credits')]


def esc(t):
    return str(t if t is not None else '').replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')


def jsd(o):
    return json.dumps(o, ensure_ascii=False).replace('</', '<\\/')


def load():
    def rd(p, default):
        try:
            return json.load(open(WORLD / p, encoding='utf-8'))
        except Exception:
            return default
    N = rd('news.json', {'updated': '', 'days': []})
    days = sorted(N.get('days', []), key=lambda d: d['date'], reverse=True)
    plates = sorted(rd('plates.json', []), key=lambda p: p['date'], reverse=True)
    weekly = sorted(rd('weekly.json', []), key=lambda w: w.get('date', ''), reverse=True)
    return N, days, plates, weekly


def original_plates(index_html):
    """The nine opening Daily Masterworks are listed in the page itself (const PLATES=[...])."""
    m = re.search(r'const PLATES=(\[.*?\n\]);', index_html, re.S)
    if not m:
        return []
    try:
        rows = json.loads(m.group(1))
    except Exception:
        return []
    out = []
    for r in rows:
        artist = r[2].split(' — ')[0]
        out.append({'id': r[0], 'title': r[1], 'artist': artist, 'meta': r[2], 'license': r[3], 'credit': 'Wikimedia Commons',
                    'url': 'https://commons.wikimedia.org/wiki/File:' + r[4], 'file': r[0] + '.webp', 'w': int(r[5]), 'h': int(r[6]), 'date': '2026-10-12', 'source': 'Wikimedia Commons'})
    return out


def styles(index_html):
    return ''.join(f'<style>{s}</style>' for s in re.findall(r'<style>(.*?)</style>', index_html, re.S))


