def fmt(d):
    return datetime.strptime(d, '%Y-%m-%d').strftime('%d %b %Y').upper()


def fmt_ja(d):
    t = datetime.strptime(d, '%Y-%m-%d')
    return f'{t.year}年{t.month}月{t.day}日'


def day_path(d):
    return d.replace('-', '/') + '/'


def shell(title, desc, body, root, lang='ja', canonical='', og_image='', extra_head='', ld=None, alt=None, noindex=False):
    """One page in the same clothes as synesthesia-world/index.html (its CSS is reused as is).
    root: relative path from the page to synesthesia-world/ (e.g. '../../../')."""
    idx = shell.index_html
    nav = ''.join(f'<a href="{root}{h if not h.startswith("#") else "index.html" + h}">{esc(n)}</a>' for n, h in NAV)
    og_image = og_image or BASE + 'media/film-poster.jpg'
    alts = ''
    if alt:
        alts = ''.join(f'<link rel="alternate" hreflang="{l}" href="{u}">' for l, u in alt.items()) + f'<link rel="alternate" hreflang="x-default" href="{alt.get("ja", canonical)}">'
    ldjs = f'<script type="application/ld+json">{jsd(ld)}</script>' if ld else ''
    home_lab = '← Kengo Umetani Official' if lang == 'ja' else '← Kengo Umetani Official'
    return f'''<!doctype html>
<html lang="{lang}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>{esc(title)} | KENGO'S SYNESTHESIA</title>
<meta name="description" content="{esc(desc)}">
{'<meta name="robots" content="noindex, follow">' if noindex else ''}<link rel="canonical" href="{canonical}">
{alts}
<meta property="og:type" content="article">
<meta property="og:site_name" content="KENGO'S SYNESTHESIA">
<meta property="og:title" content="{esc(title)}">
<meta property="og:description" content="{esc(desc)}">
<meta property="og:url" content="{canonical}">
<meta property="og:image" content="{og_image}">
{'<meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">' if og_image.endswith(".png") else ""}
<meta property="og:locale" content="{'ja_JP' if lang == 'ja' else 'en_US'}">
<meta name="twitter:card" content="summary_large_image">
<link rel="alternate" type="application/atom+xml" title="KENGO'S SYNESTHESIA" href="{BASE}feed.xml">
<link rel="alternate" type="application/feed+json" title="KENGO'S SYNESTHESIA" href="{BASE}feed.json">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Zen+Kaku+Gothic+New:wght@400;500&display=swap">
{styles(idx)}{EXTRA_CSS}{extra_head}{ldjs}
</head>
<body data-static>
<div class="wrap">
  <header class="hd"><h1 class="mast"><a href="{root}">KENGO'S SYNESTHESIA</a></h1><nav class="nv" aria-label="{'サイト内' if lang == 'ja' else 'Site'}"><a href="{root}../">{home_lab}</a>{nav}</nav></header>
{body}
  <footer class="lab"><span>KENGO'S SYNESTHESIA — Kengo Umetani</span><span>Issue 01 — 2026</span></footer>
</div>
{shell.analytics}
</body>
</html>
'''


shell.index_html = ''
shell.analytics = ''


# ---------- blocks shared by the day page and the lists ----------

def note_block(day, lang):
    n = day.get('note') or {}
    if not n.get('ja') and not n.get('en'):
        return ''
    en = f'<p class="ken">{esc(n.get("en", ""))}</p>' if n.get('en') else ''
    ja = f'<p class="kja">{esc(n.get("ja", ""))}</p>' if n.get('ja') and lang == 'ja' else ''
    src = f'<a class="src" href="{esc(n["url"])}" target="_blank" rel="noopener">{esc(n.get("source", "Source"))}</a>' if n.get('url') else ''
    return f'<div class="knote"><div><span class="lab">Kengo\'s Note</span><span class="kt">{esc(n.get("title", ""))}</span></div><div>{en}{ja}{src}</div></div>'


def story(i, lang, when=''):
    jp = '<span class="jp">From Japan</span>' if i.get('japan') else ''
    if i.get('cat') == 'art':
        jp += '<span class="jp">Art</span>'
    text = i.get('ja', '') if lang == 'ja' else (i.get('en') or '')
    sm = f'<span class="sm">{esc(text)}</span>' if text else ''
    return (f'<article>{f"<span class=\"when\">{esc(when)}</span>" if when else ""}<a href="{esc(i.get("url", "#"))}" target="_blank" rel="noopener"><span class="hl">{esc(i.get("title", ""))}{jp}</span>{sm}<span class="src">{esc(i.get("source", ""))}</span></a></article>')


def japan_list(items, lang, when=None):
    """From Japan: the Japan Art stories (exhibitions, artists, galleries) first under their own label, then the rest."""
    art = [x for x in items if x.get('cat') == 'art']
    rest = [x for x in items if x.get('cat') != 'art']
    T = (lambda ja, en: ja if lang == 'ja' else en)
    out = ''
    if art:
        out += f'<span class="glab">Japan Art <small>{T("展覧会・作家・ギャラリー", "Exhibitions, artists and galleries")}</small></span>'
        out += ''.join(story(x, lang, when=when(x) if when else '') for x in art)
    if rest:
        if art:
            out += f'<span class="glab">{T("デザイン・建築・ファッション・音楽", "Design, architecture, fashion and music")}</span>'
        out += ''.join(story(x, lang, when=when(x) if when else '') for x in rest)
    return out


def news_grid(day, lang):
    cols = ''
    for k, label in CATS:
        items = [i for i in day.get('items', []) if i.get('cat') == k]
        if not items:
            continue
        cols += f'<div class="col"><span class="lab">{label}</span>' + ''.join(story(i, lang) for i in items) + '</div>'
    return f'<div class="news">{cols}</div>' if cols else ''


def object_card(o, lang, when=''):
    text = o.get('ja', '') if lang == 'ja' else (o.get('en') or '')
    buy = o.get('buy') or o.get('url') or '#'
    rel = 'sponsored noopener' if o.get('buy') else 'noopener'
    ship = {'worldwide': 'Ships worldwide', 'japan': 'Japan only'}.get(o.get('ships', ''), '')
    pr = '<span class="pr">PR</span>' if o.get('buy') else ''
    brand = f'{esc(o["brand"])} — ' if o.get('brand') else ''
    return (f'<article>{pr}{f"<span class=\"when\">{esc(when)}</span>" if when else ""}<span class="hl">{brand}{esc(o.get("name", ""))}{"<span class=\"jp\">From Japan</span>" if o.get("japan") else ""}</span>'
            f'<span class="sm">{esc(text)}</span><a class="buy" href="{esc(buy)}" target="_blank" rel="{rel}">{"見る" if lang == "ja" else "View"}{f" · {esc(o['price'])}" if o.get("price") else ""}</a>'
            f'{f"<span class=\"ship\">{ship}</span>" if ship else ""}</article>')


def plate_figure(p, lang, root):
    meta = ', '.join(x for x in [p.get('artist'), p.get('when')] if x) + (f' — {p["medium"].lower()}' if p.get('medium') else '')
    if p.get('meta'):
        meta = p['meta']
    lic = f'{p.get("license", "")} · {p.get("credit", "")}'
    return (f'<figure><div class="im"><img src="{root}media/{esc(p["file"])}" width="{p["w"]}" height="{p["h"]}" alt="{esc(p["title"] + " — " + meta)}"></div>'
            f'<figcaption><span class="no">{esc(fmt(p["date"]))}</span><span><span class="t">{esc(p["title"])}</span><span class="m">{esc(meta)} · {esc(lic)} · <a href="{esc(p["url"])}" target="_blank" rel="noopener">Source</a></span></span></figcaption></figure>')


def signal_block(day, root, lang):
    """The day's SYNESTHESIA DIGITAL ART, drawn live by signal.js from this day's data."""
    data = jsd({'updated': day['date'], 'days': [day]})
    return (f'<script type="application/json" id="news-data">{data}</script>'
            f'<div class="film signal day"><canvas id="signal" aria-label="SYNESTHESIA DIGITAL ART by KENGO — {esc(day["date"])}"></canvas>'
            f'<div class="cap"><span><b id="signalName">SYNESTHESIA DIGITAL ART by KENGO</b> — <span id="signalData">Drawn from this day\'s data.</span></span><span id="signalJa">{"この日のデータから描いています。" if lang == "ja" else ""}</span></div></div>'
            f'<script src="{root}signal.js" defer></script>')


# ---------- pages ----------

def og_for(day, plates, art_dir):
    d = day['date']
    if (art_dir / f'{d}.png').exists():
        return BASE + f'art/{d}.png'
    p = next((p for p in plates if p['date'] == d), None)
    if p:
        return BASE + 'media/' + p['file']
    return ''


def day_page(day, days, plates, art_dir, lang):
    d = day['date']
    i = days.index(day)
    prev_d = days[i + 1]['date'] if i + 1 < len(days) else None
    next_d = days[i - 1]['date'] if i > 0 else None
    root = '../../../' + ('../' if lang == 'en' else '')
    note = day.get('note') or {}
    title = f'{fmt(d)} — {note.get("title") or "Today"}'
    desc = (note.get('ja') if lang == 'ja' else note.get('en')) or ', '.join(i.get('title', '') for i in day.get('items', [])[:3])
    desc = (desc or '')[:150]
    url = BASE + ('en/' if lang == 'en' else '') + day_path(d)
    alt = {'ja': BASE + day_path(d), 'en': BASE + 'en/' + day_path(d)}
    plate = next((p for p in plates if p['date'] == d), None)
    japan = [x for x in day.get('items', []) if x.get('japan')]
    objects = day.get('objects') or ([day['object']] if day.get('object') else [])
    T = (lambda ja, en: ja if lang == 'ja' else en)
    body = f'''  <div class="dayhead"><span class="lab">KENGO'S SYNESTHESIA — {T("毎日の号", "Daily issue")}</span>
    <h1>{esc(fmt(d))}<small>{esc(note.get("title", ""))}</small></h1>
    <p>{T(f"{fmt_ja(d)}の KENGO'S SYNESTHESIA。この日のノート、デジタルアート、作品、ニュースをひとつのページに残しています。", f"KENGO'S SYNESTHESIA for {fmt(d).title()}: the note, the digital art, the daily masterwork and the stories of the day on one page.")}</p>
  </div>
  <section id="note"><h2>Kengo's Note <small>{esc(fmt(d))}</small></h2>{note_block(day, lang)}</section>
  <section id="art"><h2>Synesthesia Digital Art by Kengo <small>{T("この日のデータから生まれたアート", "Art drawn from this day's data")}</small></h2>{signal_block(day, root, lang)}</section>
'''
    if plate:
        body += f'  <section id="plates-sec"><h2>Daily Masterwork <small>{T("この日の作品", "The daily masterwork")}</small></h2><div class="plate1">{plate_figure(plate, lang, root)}</div></section>\n'
    body += f'  <section id="today"><h2>Today <small>{esc(fmt(d))}</small></h2>{news_grid(day, lang)}</section>\n'
    if japan:
        body += f'  <section id="japan"><h2>From Japan <small>{T("日本から世界へ", "Japan to the world")}</small></h2><div class="col-list">{japan_list(japan, lang)}</div></section>\n'
    if objects:
        body += f'  <section id="objects"><h2>Objects <small>{T("今日の良いもの", "One good thing")}</small></h2><div class="objects">{"".join(object_card(o, lang) for o in objects)}</div></section>\n'
    pv = f'<a href="{root}{"en/" if lang == "en" else ""}{day_path(prev_d)}">← {esc(fmt(prev_d))}</a>' if prev_d else '<span></span>'
    nx = f'<a href="{root}{"en/" if lang == "en" else ""}{day_path(next_d)}">{esc(fmt(next_d))} →</a>' if next_d else f'<a href="{root}{"en/" if lang == "en" else ""}">{T("最新へ", "Latest")} →</a>'
    body += f'  <div class="pager">{pv}{nx}</div>\n'
    ld = {'@context': 'https://schema.org', '@type': 'Article', 'headline': title, 'datePublished': f'{d}T07:30:00+09:00', 'dateModified': f'{d}T07:30:00+09:00',
          'inLanguage': 'ja' if lang == 'ja' else 'en', 'author': {'@type': 'Person', 'name': 'Kengo Umetani', 'url': 'https://www.kengo-umetani.com/'},
          'publisher': {'@type': 'Person', 'name': 'Kengo Umetani'}, 'mainEntityOfPage': url, 'url': url, 'isPartOf': {'@type': 'WebSite', 'name': "KENGO'S SYNESTHESIA", 'url': BASE}}
    og = og_for(day, plates, art_dir)
    if og:
        ld['image'] = og
    if plate:
        ld['associatedMedia'] = {'@type': 'ImageObject', 'name': plate['title'], 'contentUrl': BASE + 'media/' + plate['file'], 'license': plate.get('url'), 'creditText': plate.get('credit')}
    return shell(title, desc, body, root, lang, url, og, ld=ld, alt=alt)


def notes_page(days, lang='ja'):
    root = '../'
    items = ''
    for day in days:
        n = day.get('note') or {}
        if not n.get('title'):
            continue
        items += (f'<article><span class="when"><a href="{root}{day_path(day["date"])}">{esc(fmt(day["date"]))}</a></span><a href="{root}{day_path(day["date"])}#note"><span class="hl">{esc(n["title"])}</span></a>'
                  f'{f"<span class=\"en\">{esc(n.get('en', ''))}</span>" if n.get("en") else ""}{f"<span class=\"sm\">{esc(n.get('ja', ''))}</span>" if n.get("ja") else ""}'
                  f'{f"<a class=\"src\" href=\"{esc(n['url'])}\" target=\"_blank\" rel=\"noopener\">{esc(n.get('source', 'Source'))}</a>" if n.get("url") else ""}</article>')
    body = f'''  <div class="dayhead"><span class="lab">KENGO'S SYNESTHESIA</span><h1>Kengo's Note<small>建築家の眼、クリエイティブディレクターの眼 — every note, newest first</small></h1>
    <p>建築を学び、ランウェイに立ち、いまはホテルやリゾートの空間をつくる梅谷憲吾が、その日いちばん心に残ったアートについて書いたノートのすべてです。空間、光、素材、身体、そして場所が人に与える感覚から見ています。</p></div>
  <section><div class="col-list">{items}</div></section>
'''
    ld = {'@context': 'https://schema.org', '@type': 'CollectionPage', 'name': "Kengo's Note", 'url': BASE + 'notes/', 'author': {'@type': 'Person', 'name': 'Kengo Umetani'}}
    return shell("Kengo's Note", "梅谷憲吾が毎日ひとつのアートについて書くノートの一覧。", body, root, lang, BASE + 'notes/', ld=ld)


def weekly_entry(w, lang, root, full=True):
    text_en = w.get('en', '')
    text_ja = w.get('ja', '')
    picks = ''.join(f'<li><a href="{esc(p.get("url", "#"))}" target="_blank" rel="noopener"><span class="hl">{esc(p.get("title", ""))}</span><span class="sm">{esc(p.get("ja", "") if lang == "ja" else p.get("en", ""))}</span></a></li>' for p in w.get('picks', []))
    paras = lambda t: ''.join(f'<p class="ken">{esc(x.strip())}</p>' for x in (t or '').split('\n') if x.strip())
    paras_ja = lambda t: ''.join(f'<p class="kja">{esc(x.strip())}</p>' for x in (t or '').split('\n') if x.strip())
    return (f'<div class="knote"><div><span class="lab">Weekly Synesthesia</span><span class="kt"><a href="{root}weekly/{esc(w["id"])}/">{esc(w.get("title", ""))}</a></span><span class="lab" style="margin-top:6px">{esc(fmt(w["date"]))}</span></div>'
            f'<div>{paras(text_en)}{paras_ja(text_ja) if lang == "ja" else ""}{f"<ul class=\"picks\">{picks}</ul>" if picks and full else ""}</div></div>')


def weekly_pages(weekly, lang='ja'):
    out = {}
    root = '../'
    lst = ''.join(weekly_entry(w, lang, root, full=False) for w in weekly) or '<p class="intro">まだありません。最初の号は次の日曜日に。</p>'
    body = f'''  <div class="dayhead"><span class="lab">KENGO'S SYNESTHESIA</span><h1>Weekly Synesthesia<small>日曜日の編集後記 — the week, looked back on every Sunday</small></h1>
    <p>毎日の自動更新の上に、週に一度だけ人の視点を置きます。1週間のニュースから残ったもの、気になった5つ、そこから考えたこと。</p></div>
  <section>{lst}</section>
'''
    out['weekly/index.html'] = shell('Weekly Synesthesia', '日曜日の編集後記。1週間のファッション・音楽・デザインのニュースを振り返る短いコラム。', body, root, lang, BASE + 'weekly/')
    for w in weekly:
        r = '../../'
        body = f'''  <div class="dayhead"><span class="lab">Weekly Synesthesia — {esc(fmt(w["date"]))}</span><h1>{esc(w.get("title", ""))}</h1></div>
  <section>{weekly_entry(w, lang, r)}</section>
  <div class="pager"><a href="{r}weekly/">← Weekly Synesthesia</a><a href="{r}">KENGO'S SYNESTHESIA →</a></div>
'''
        url = BASE + f'weekly/{w["id"]}/'
        ld = {'@context': 'https://schema.org', '@type': 'Article', 'headline': w.get('title', ''), 'datePublished': f'{w["date"]}T07:30:00+09:00', 'author': {'@type': 'Person', 'name': 'Kengo Umetani'}, 'url': url}
        out[f'weekly/{w["id"]}/index.html'] = shell(w.get('title', 'Weekly Synesthesia'), (w.get('ja') or w.get('en') or '')[:150], body, r, lang, url, ld=ld)
    return out


